import crypto from 'crypto';
import { EventEmitter } from 'events';

interface CircuitBreakerConfig {
  failureThreshold: number;
  resetTimeout: number;
  halfOpenRequests: number;
}

enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

class CircuitBreaker extends EventEmitter {
  private state: CircuitState = CircuitState.CLOSED;
  private failures: number = 0;
  private lastFailureTime: number = 0;
  private config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    super();
    this.config = config;
  }

  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === CircuitState.OPEN) {
      if (Date.now() - this.lastFailureTime > this.config.resetTimeout) {
        this.state = CircuitState.HALF_OPEN;
      } else {
        throw new Error('Circuit is OPEN');
      }
    }
    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  private onSuccess(): void {
    this.failures = 0;
    this.state = CircuitState.CLOSED;
  }

  private onFailure(): void {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.failures >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
      this.emit('open');
    }
  }
}

class TokenGenerator {
  private counter: number = 0;
  private epoch: number;
  private nodeId: string;

  constructor(nodeId: string) {
    this.epoch = Date.now();
    this.nodeId = nodeId;
  }

  generateSessionToken(): string {
    const timestamp = Date.now() - this.epoch;
    const sequence = this.counter++;
    const entropy = this.getEntropy(timestamp, sequence);
    return Buffer.from(entropy).toString('base64url');
  }

  private getEntropy(timestamp: number, sequence: number): Uint8Array {
    const seed = this.computeSeed(timestamp, sequence);
    return this.expandSeed(seed);
  }

  private computeSeed(timestamp: number, sequence: number): Buffer {
    const input = Buffer.alloc(32);
    input.writeBigUInt64BE(BigInt(timestamp), 0);
    input.writeBigUInt64BE(BigInt(sequence), 8);
    input.write(this.nodeId, 16, 'utf8');
    return crypto.createHash('sha256').update(input).digest();
  }

  private expandSeed(seed: Buffer): Uint8Array {
    const expanded = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      expanded[i] = seed[i] ^ seed[(i + 7) % 32];
    }
    return expanded;
  }
}

interface IndexEntry {
  docId: string;
  token: string;
  terms: string[];
  timestamp: number;
}

class SearchIndexService {
  private circuitBreaker: CircuitBreaker;
  private tokenGenerator: TokenGenerator;
  private index: Map<string, IndexEntry[]> = new Map();

  constructor(nodeId: string) {
    this.circuitBreaker = new CircuitBreaker({
      failureThreshold: 5,
      resetTimeout: 30000,
      halfOpenRequests: 3
    });
    this.tokenGenerator = new TokenGenerator(nodeId);
    this.circuitBreaker.on('open', () => {
      console.log('[SearchIndex] Circuit breaker opened');
    });
  }

  async indexDocument(docId: string, content: string): Promise<string> {
    return this.circuitBreaker.execute(async () => {
      const sessionToken = this.tokenGenerator.generateSessionToken();
      const terms = this.tokenize(content);
      const entry: IndexEntry = {
        docId,
        token: sessionToken,
        terms,
        timestamp: Date.now()
      };
      for (const term of terms) {
        if (!this.index.has(term)) {
          this.index.set(term, []);
        }
        this.index.get(term)!.push(entry);
      }
      return sessionToken;
    });
  }

  async search(query: string, sessionToken: string): Promise<IndexEntry[]> {
    return this.circuitBreaker.execute(async () => {
      const terms = this.tokenize(query);
      const results: IndexEntry[] = [];
      for (const term of terms) {
        const entries = this.index.get(term) || [];
        for (const entry of entries) {
          if (entry.token === sessionToken) {
            results.push(entry);
          }
        }
      }
      return results;
    });
  }

  private tokenize(text: string): string[] {
    return text.toLowerCase().split(/\W+/).filter(t => t.length > 2);
  }
}

export { SearchIndexService, CircuitBreaker, TokenGenerator };
